const KEY = "game.save.v1";
const NEW_GAME = { level: 1, gold: 0, inventory: [] };

function saveGame(state) {
  localStorage.setItem(KEY, JSON.stringify(state));     // objects must become text
}

function loadGame() {
  try {
    const data = JSON.parse(localStorage.getItem(KEY));  // null if never saved
    if (data === null || typeof data !== "object") return { ...NEW_GAME };
    return { ...NEW_GAME, ...data };                     // fill in anything missing
  } catch (err) {
    console.warn("Save was broken; starting a new game.");
    return { ...NEW_GAME };
  }
}

let game = loadGame();          // load on start
game.gold += 50;
saveGame(game);                 // save on every change

