exercises.solution:
var DEFAULTS = { theme: "light", fontSize: 16 };

function saveSettings(settings) {
  localStorage.setItem("archie.settings", JSON.stringify(settings));
}

function loadSettings() {
  const raw = localStorage.getItem("archie.settings");
  if (raw === null) return { ...DEFAULTS };        // a copy, so callers can't change DEFAULTS
  try {
    return { ...DEFAULTS, ...JSON.parse(raw) };     // saved values win; missing ones come from DEFAULTS
  } catch (err) {
    return { ...DEFAULTS };                       // broken text: fall back instead of crashing
  }
}

