function saveStock(stock) {
  localStorage.setItem("clinic.stock", JSON.stringify(stock));
}

function isGoodItem(item) {
  // typeof null is "object", so rule null out first
  return item !== null && typeof item === "object" && typeof item.name === "string" && Number.isFinite(item.qty);
}

function loadStock() {
  let data;
  try {
    data = JSON.parse(localStorage.getItem("clinic.stock"));   // JSON.parse(null) is null
  } catch (err) {
    return [];
  }
  if (!Array.isArray(data)) return [];
  return data.filter(isGoodItem);
}

