var KEY = "water.buckets";

function loadCount() {
  const n = Number(localStorage.getItem(KEY));   // Number(null) is 0
  return Number.isInteger(n) && n >= 0 ? n : 0;
}

function saveCount(n) {
  localStorage.setItem(KEY, String(n));
}

function totalText(n) {
  return `${n} ${n === 1 ? "bucket" : "buckets"} (${n * 20} L)`;
}

var buckets = loadCount();            // load on start

function show() {
  document.getElementById("total").textContent = totalText(buckets);
}

document.getElementById("add-bucket").addEventListener("click", () => {
  buckets++;
  saveCount(buckets);                 // save on every change
  show();
});

document.getElementById("reset").addEventListener("click", () => {
  buckets = 0;
  saveCount(buckets);
  show();
});

show();
